import { BrowserRouter as Router, Route, Routes, Navigate } from "react-router-dom";
import './SignUp/SignUp.css';
import './LogIn/logIn.css';
import './HomePage/HomePage.css';
import { useState } from 'react';

import SignUp from './SignUp/SignUp.js';
import LogIn from './LogIn/logIn.js';
import HomePage from './HomePage/HomePage.js';

function App() {
  const [activeUser, setActiveUser] = useState('');
 // const [usersList, setUsersList] = useState('');

  const setActiveUserByToken = async (token, email) => {
    console.log("token: ", token);
    const response = await fetch('http://localhost:8080/api/users/?email=${email}' , {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`
      }
    });
      const user = await response.json();
      setActiveUser({
        firstName: user.firstName,
        lastName: user.lastName,
        displayName: user.displayName,
        email: user.email,
        //picture: user.picture,
        token: token
      });
    }


  
  return (
    <div className="App">
      <header className="App-header">
        <Router>
          <Routes>
            <Route path="" element={<LogIn setActiveUserByToken={setActiveUserByToken}  />} />
            <Route path="/SignUp" element={<SignUp />} />
            <Route path="/HomePage" element={activeUser ? <HomePage activeUser={activeUser} /> : <Navigate to="/ " />} />
          </Routes>
        </Router>
      </header>
    </div>
  );
}

export default App;
